def get_min_string(s):
    # 将字符串转成列表，方便修改字符
    chars = list(s)
    n = len(chars)

    # 找到第一个替换为镜面字母后会变小的字符，即 'n' 到 'z'
    i = 0
    while i < n and chars[i] <= 'm':
        i += 1

    # 从该位置开始，连续进行镜面替换所有会变小的字符
    while i < n and chars[i] >= 'n':
        chars[i] = chr(ord('a') + ord('z') - ord(chars[i]))
        i += 1

    return ''.join(chars)


